        if k == 0:
            return True
        n = len(s)
        first = {}
        last = {}
        for i, c in enumerate(s):
            if c not in first:
                first[c] = i
            last[c] = i

        intervals = []
        for i in range(n):
            if first[s[i]] != i:
                continue
            j = last[s[i]]
            valid = True
            p = i
            while p <= j:
                c = s[p]
                if first[c] < i:
                    valid = False
                    break
                if last[c] > j:
                    j = last[c]
                p += 1
            if not valid:
                continue
            if i == 0 and j == n - 1:
                continue
            intervals.append((i, j))

        intervals.sort(key=lambda x: x[1])
        count = 0
        prev_end = -1
